def transform(grid):
    """Trace a 2-ray through 8-barriers, routing through their zero gaps."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    starts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not starts:
        return out

    queue = deque()
    for r, c in starts:
        if r == 0:
            queue.append((r, c, 1, 0))
        elif r == h - 1:
            queue.append((r, c, -1, 0))
        elif c == 0:
            queue.append((r, c, 0, 1))
        elif c == w - 1:
            queue.append((r, c, 0, -1))

    visited_rays = set()
    while queue:
        r, c, dr, dc = queue.popleft()
        state = (r, c, dr, dc)
        if state in visited_rays:
            continue
        visited_rays.add(state)
