 "content": "def _canonical(grid):
    """Rotate/reflect so the marker is on the top edge, launching down."""
    h, w = len(grid), len(grid[0])
    marker = next(((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if marker is None:
        return [row[:] for row in grid], "none"
    r, c = marker
    if r == 0:
        return [row[:] for row in grid], "top"
    if r == h - 1:
        return [row[:] for row in grid[::-1]], "bottom"
    transposed = [list(row) for row in zip(*grid)]
    if c == 0:
        return transposed, "left"
    if c == w - 1:
        return transposed[::-1], "right"
    return [row[:] for row in grid], "none"


def transform(grid):
    a, orientation = _canonical(grid)
    if orientation == "none":
        return [row[:] for row in grid]
    h, w = len(a), len(a[0])
    out = [row[:] for row in a]
    marker = next((r, c) for r in range(h) for c in range(w) if a[r][c] == 2)
    _, start = marker

    # A perforated 8-stripe acts as a wall. A beam that hits it spreads along
    # the adjacent open lane to the nearest aperture on each side, then passes
    # through those apertures. If a side has no aperture, the lane reaches edge.
    stripes = [r for r in range(1, h) if sum(v == 8 for v in a[r]) > w / 2]
    active = {start}
    previous = 0
    for stripe in stripes:
        lane = stripe - 1
        for r in range(previous + 1, stripe):
            for c in active:
                if a[r][c] != 8:
                    out[r][c] = 2

        holes = [c for c, value in enumerate(a[stripe]) if value != 8]
        crossed = set()
        for c in active:
            if c in holes:
                out[stripe][c] = 2
                crossed.add(c)
                continue
            for side in (-1, 1):
                candidates = [x for x in holes if (x - c) * side > 0]
                if candidates:
                    target = min(candidates) if side > 0 else max(candidates)
                    for x in range(min(c, target), max(c, target) + 1):
                        if a[lane][x] != 8:
                            out[lane][x] = 2
                    out[stripe][target] = 2
                    crossed.add(target)
                else:
                    edge = 0 if side < 0 else w - 1
                    for x in range(min(c, edge), max(c, edge) + 1):
                        if a[lane][x] != 8:
                            out[lane][x] = 2
        active = crossed
        previous = stripe
        if not active:
            break

    for r in range(previous + 1, h):
        for c in active:
            if a[r][c] != 8:
                out[r][c] = 2

    if orientation == "bottom":
        out.reverse()
    elif orientation == "left":
        out = [list(row) for row in zip(*out)]
    elif orientation == "right":
        out = [list(row) for row in zip(*out[::-1])]
    return out
